// Choose the event to grade.
// - Scheduled run: the most recent finished event that has not been graded yet.
// - On demand (/grade [text]): the most recent finished event, or the one matching the text.

const OWNER_CHAT_ID = 0;
const ENDED_AFTER_HOURS = 4;
const BACKFILL_DAYS = 180;
const NOTIFY_WITHIN_DAYS = 3;

const nowMs = Date.now();

let trigger = {};

try {
  trigger = $('Grade On Demand').first().json || {};
} catch {
  // Scheduled run: the on-demand trigger did not fire.
}

const forced = Object.keys(trigger).length > 0;
const chatId = trigger.chat_id || OWNER_CHAT_ID;

const normalise = (value) =>
  String(value ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

const needle = normalise(trigger.args);

const candidates = $input
  .all()
  .map((item) => item.json)
  .filter((row) => row.event_key && row.spreadsheet_id && row.event_datetime_local)
  .map((row) => ({ row, startMs: Date.parse(row.event_datetime_local) }))
  .filter((entry) => Number.isFinite(entry.startMs))
  .filter((entry) => nowMs - entry.startMs >= ENDED_AFTER_HOURS * 3600 * 1000);

let pool;

if (forced) {
  pool = needle
    ? candidates.filter((entry) =>
        normalise(`${entry.row.event_key} ${entry.row.event_name}`).includes(needle)
      )
    : candidates;
} else {
  pool = candidates.filter(
    (entry) =>
      !entry.row.graded_at &&
      nowMs - entry.startMs <= BACKFILL_DAYS * 24 * 3600 * 1000
  );
}

pool.sort((a, b) => b.startMs - a.startMs);

if (pool.length === 0) {
  return forced
    ? [
        {
          json: {
            abort: true,
            chat_id: chatId,
            message: needle
              ? `No finished event matched "${trigger.args}".`
              : 'No finished event to grade yet.',
          },
        },
      ]
    : [];
}

const chosen = pool[0];

return [
  {
    json: {
      ...chosen.row,
      abort: false,
      forced,
      chat_id: chatId,
      notify: forced || nowMs - chosen.startMs <= NOTIFY_WITHIN_DAYS * 24 * 3600 * 1000,
    },
  },
];

// Find the event on ESPN's scoreboard and list its finished fights.

const evt = $('Pick Event To Grade').first().json;
const nowMs = Date.now();
const startMs = Date.parse(evt.event_datetime_local);

const scoreboard = $input.first().json || {};
const espnEvents = Array.isArray(scoreboard.events) ? scoreboard.events : [];

const abort = (message) =>
  evt.forced ? [{ json: { abort: true, chat_id: evt.chat_id, message } }] : [];

function normaliseText(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase();
}

function buildEventKeywords(eventName) {
  const [head, ...rest] = normaliseText(eventName).split(':');
  const keywords = new Set();

  head
    .replace(/\bufc\b/g, ' ')
    .replace(/\bfight night\b/g, ' ')
    .split(/[^a-z0-9]+/)
    .filter((word) => word.length >= 3)
    .forEach((word) => keywords.add(word));

  rest
    .join(':')
    .split(/[^a-z0-9'-]+/)
    .filter((word) => word.length >= 4 && word !== 'vs')
    .forEach((word) => keywords.add(word));

  return [...keywords];
}

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const keywords = buildEventKeywords(evt.event_name);

let best = null;
let bestScore = 0;

for (const espnEvent of espnEvents) {
  const name = normaliseText(espnEvent.name);
  const score = keywords.filter((keyword) =>
    new RegExp(`\\b${escapeRegExp(keyword)}\\b`).test(name)
  ).length;

  if (score > bestScore) {
    best = espnEvent;
    bestScore = score;
  }
}

if (!best) {
  return abort(`Could not find ${evt.event_name} on ESPN.`);
}

const competitions = Array.isArray(best.competitions) ? best.competitions : [];
const finished = competitions.filter((comp) => comp.status?.type?.completed === true);

if (finished.length === 0) {
  return abort(`${evt.event_name} has no finished fights on ESPN yet.`);
}

if (finished.length < competitions.length && nowMs - startMs < 24 * 3600 * 1000) {
  return abort(
    `${evt.event_name}: ${finished.length} of ${competitions.length} fights are final. Try again later.`
  );
}

return finished.map((comp) => ({
  json: {
    event_key: evt.event_key,
    espn_event_id: best.id,
    espn_competition_id: comp.id,
    weight_class: comp.type?.abbreviation || comp.type?.text || '',
    scheduled_rounds: comp.format?.regulation?.periods ?? null,
    competitors: (comp.competitors || [])
      .map((competitor) => ({
        name: competitor.athlete?.displayName || '',
        winner: competitor.winner === true,
        order: Number(competitor.order),
      }))
      .sort((a, b) => a.order - b.order),
  },
}));

// Combine each fight's scoreboard entry with its ESPN result.

const comps = $('Match ESPN Event').all().map((item) => item.json);
const statuses = $input.all().map((item) => item.json);
const recordedAt = new Date().toISOString();

function mapMethod(name) {
  const value = String(name ?? '').toLowerCase();

  if (value === 'kotko' || value === 'ko' || value === 'tko') return 'KO_TKO';
  if (value.startsWith('submission')) return 'SUBMISSION';
  if (value.startsWith('decision')) return 'DECISION';
  if (value === 'draw') return 'DRAW';
  if (value === 'dq') return 'DQ';
  if (value === 'nc' || value.includes('no-contest') || value.includes('no contest')) {
    return 'NO_CONTEST';
  }

  return 'OTHER';
}

const rows = [];

statuses.forEach((status, index) => {
  const comp = comps[index];

  if (!comp || status?.type?.name !== 'STATUS_FINAL') return;

  const method = mapMethod(status.result?.name);
  const winnerName = comp.competitors.find((competitor) => competitor.winner)?.name ?? null;

  let winner = winnerName;

  if (method === 'DRAW') winner = 'DRAW';
  if (method === 'NO_CONTEST') winner = 'NO_CONTEST';

  const period = Number(status.period) || 0;
  const [minutes, seconds] = String(status.displayClock || '0:00')
    .split(':')
    .map((part) => Number(part) || 0);
  const clockSeconds = minutes * 60 + seconds;

  rows.push({
    json: {
      event_key: comp.event_key,
      espn_event_id: comp.espn_event_id,
      espn_competition_id: comp.espn_competition_id,
      fighter_a: comp.competitors[0]?.name ?? '',
      fighter_b: comp.competitors[1]?.name ?? '',
      winner,
      method,
      method_detail: status.result?.description || status.result?.displayName || '',
      round: period,
      clock: status.displayClock || '',
      elapsed_rounds: Math.round(((period - 1) + clockSeconds / 300) * 100) / 100,
      elapsed_minutes: Math.round(((period - 1) * 5 + clockSeconds / 60) * 100) / 100,
      scheduled_rounds: comp.scheduled_rounds,
      weight_class: comp.weight_class,
      recorded_at: recordedAt,
    },
  });
});

return rows;

// Grade each picker's winner picks against the fight results.

const evt = $('Pick Event To Grade').first().json;
const results = $('Build Fight Results').all().map((item) => item.json);
const gradedAt = new Date().toISOString();

const normaliseText = (value) =>
  String(value ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase();

function nameTokens(value) {
  return normaliseText(value)
    .replace(/[^a-z0-9\s-]/g, ' ')
    .replace(/-/g, ' ')
    .split(/\s+/)
    .filter((token) => token.length >= 2 && !['jr', 'sr', 'ii', 'iii', 'iv'].includes(token));
}

function namesMatch(a, b) {
  const tokensA = nameTokens(a);
  const tokensB = nameTokens(b);

  if (tokensA.length === 0 || tokensB.length === 0) return false;
  if (tokensA[tokensA.length - 1] === tokensB[tokensB.length - 1]) return true;

  const shared = tokensA.filter((token) => tokensB.includes(token));

  return shared.length >= 2 || (shared.length >= 1 && (tokensA.length === 1 || tokensB.length === 1));
}

function findResult(fighterA, fighterB) {
  return results.find(
    (result) =>
      (namesMatch(fighterA, result.fighter_a) && namesMatch(fighterB, result.fighter_b)) ||
      (namesMatch(fighterA, result.fighter_b) && namesMatch(fighterB, result.fighter_a))
  );
}

// One pick per picker per fight (latest extraction wins).
const latestByKey = new Map();

for (const item of $('Read Picks').all().filter((i) => !String(i.json.review_status || '').startsWith('VOID'))) {
  const row = item.json;

  if (!row.pick_id || !row.picked_fighter || !row.channel_name) continue;
  if (row.event_key && row.event_key !== evt.event_key) continue;
  if (String(row.is_official_pick).toLowerCase() === 'false') continue;

  const key = `${row.channel_name}|${row.fight_order}`;
  const existing = latestByKey.get(key);

  if (!existing || String(row.extracted_at || '') > String(existing.extracted_at || '')) {
    latestByKey.set(key, row);
  }
}

const output = [];

for (const pick of latestByKey.values()) {
  const result = findResult(pick.fighter_a, pick.fighter_b);

  let grade = 'UNMATCHED';

  if (result) {
    if (!result.winner || result.winner === 'DRAW' || result.winner === 'NO_CONTEST') {
      grade = 'VOID';
    } else {
      grade = namesMatch(pick.picked_fighter, result.winner) ? 'CORRECT' : 'INCORRECT';
    }
  }

  output.push({
    json: {
      pick_id: pick.pick_id,
      event_key: evt.event_key,
      channel_name: pick.channel_name,
      video_id: pick.video_id,
      fight_order: Number(pick.fight_order),
      fighter_a: pick.fighter_a,
      fighter_b: pick.fighter_b,
      picked_fighter: pick.picked_fighter,
      confidence_score: Number.isFinite(Number(pick.confidence_score))
        ? Number(pick.confidence_score)
        : null,
      result: grade,
      winner: result?.winner ?? '',
      graded_at: gradedAt,
    },
  });
}

return output.length > 0 ? output : [{ json: { row_type: 'none' } }];

// Grade the gradable props: method, method + round, inside the distance,
// over/under rounds and fight duration. Everything else is left UNGRADED.

const evt = $('Pick Event To Grade').first().json;
const results = $('Build Fight Results').all().map((item) => item.json);
const gradedAt = new Date().toISOString();

const normaliseText = (value) =>
  String(value ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase();

function nameTokens(value) {
  return normaliseText(value)
    .replace(/[^a-z0-9\s-]/g, ' ')
    .replace(/-/g, ' ')
    .split(/\s+/)
    .filter((token) => token.length >= 2 && !['jr', 'sr', 'ii', 'iii', 'iv'].includes(token));
}

function namesMatch(a, b) {
  const tokensA = nameTokens(a);
  const tokensB = nameTokens(b);

  if (tokensA.length === 0 || tokensB.length === 0) return false;
  if (tokensA[tokensA.length - 1] === tokensB[tokensB.length - 1]) return true;

  const shared = tokensA.filter((token) => tokensB.includes(token));

  return shared.length >= 2 || (shared.length >= 1 && (tokensA.length === 1 || tokensB.length === 1));
}

function findResult(fighterA, fighterB) {
  return results.find(
    (result) =>
      (namesMatch(fighterA, result.fighter_a) && namesMatch(fighterB, result.fighter_b)) ||
      (namesMatch(fighterA, result.fighter_b) && namesMatch(fighterB, result.fighter_a))
  );
}

const methodMap = {
  ko_tko: 'KO_TKO',
  submission: 'SUBMISSION',
  decision: 'DECISION',
};

function gradeProp(row, result) {
  const winnerKnown =
    result.winner && result.winner !== 'DRAW' && result.winner !== 'NO_CONTEST';

  if (!winnerKnown) return 'VOID';

  const market = String(row.market || '');
  const selection = String(row.selection || '');
  const fighterWon = row.fighter ? namesMatch(row.fighter, result.winner) : null;

  if (market === 'method_of_victory' || market === 'method_and_round') {
    const method = methodMap[String(row.method || '').toLowerCase()];

    if (!row.fighter || !method) return 'UNGRADED';

    let correct = fighterWon && result.method === method;

    if (market === 'method_and_round') {
      const round = Number(row.round);
      const range = String(row.round_range || '').match(/R?(\d)\s*-\s*R?(\d)/i);

      if (Number.isFinite(round) && row.round !== null && row.round !== '') {
        correct = correct && result.round === round;
      } else if (range) {
        correct = correct && result.round >= Number(range[1]) && result.round <= Number(range[2]);
      }
    }

    return correct ? 'CORRECT' : 'INCORRECT';
  }

  if (market === 'inside_distance') {
    if (!row.fighter) return 'UNGRADED';

    return fighterWon && (result.method === 'KO_TKO' || result.method === 'SUBMISSION')
      ? 'CORRECT'
      : 'INCORRECT';
  }

  if (market === 'over_under_rounds') {
    const match = selection.match(/(over|under)\s*([\d.]+)\s*round/i);

    if (!match) return 'UNGRADED';

    const line = Number(match[2]);
    const isOver = match[1].toLowerCase() === 'over';

    return (isOver ? result.elapsed_rounds > line : result.elapsed_rounds < line)
      ? 'CORRECT'
      : 'INCORRECT';
  }

  if (market === 'fight_duration') {
    const match = selection.match(/(over|under)\s*([\d.]+)\s*min/i);

    if (!match) return 'UNGRADED';

    const line = Number(match[2]);
    const isOver = match[1].toLowerCase() === 'over';

    return (isOver ? result.elapsed_minutes > line : result.elapsed_minutes < line)
      ? 'CORRECT'
      : 'INCORRECT';
  }

  return 'UNGRADED';
}

const seen = new Set();
const output = [];

for (const item of $('Read Props').all().filter((i) => !String(i.json.review_status || '').startsWith('VOID'))) {
  const row = item.json;

  if (!row.prop_id || !row.channel_name || seen.has(row.prop_id)) continue;
  if (row.event_key && row.event_key !== evt.event_key) continue;

  seen.add(row.prop_id);

  const result = findResult(row.fighter_a, row.fighter_b);
  const grade = result ? gradeProp(row, result) : 'UNMATCHED';

  output.push({
    json: {
      prop_id: row.prop_id,
      event_key: evt.event_key,
      channel_name: row.channel_name,
      video_id: row.video_id,
      fight_order: Number(row.fight_order),
      market: row.market,
      selection: row.selection,
      recommendation_strength: row.recommendation_strength || '',
      result: grade,
      graded_at: gradedAt,
    },
  });
}

return output.length > 0 ? output : [{ json: { row_type: 'none' } }];

// Build the post-event scorecard message.

const evt = $('Pick Event To Grade').first().json;
const results = $('Build Fight Results').all().map((item) => item.json);
const pickGrades = $('Grade Picks').all().map((item) => item.json).filter((row) => row.pick_id);
const propGrades = $('Grade Props').all().map((item) => item.json).filter((row) => row.prop_id);

const escapeHtml = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const percent = (correct, total) => (total > 0 ? Math.round((correct / total) * 100) : 0);

const pickers = new Map();

const statsFor = (name) => {
  if (!pickers.has(name)) {
    pickers.set(name, { name, pickCorrect: 0, pickTotal: 0, propCorrect: 0, propTotal: 0 });
  }

  return pickers.get(name);
};

for (const grade of pickGrades) {
  if (grade.result !== 'CORRECT' && grade.result !== 'INCORRECT') continue;

  const stats = statsFor(grade.channel_name);
  stats.pickTotal += 1;
  if (grade.result === 'CORRECT') stats.pickCorrect += 1;
}

for (const grade of propGrades) {
  if (grade.result !== 'CORRECT' && grade.result !== 'INCORRECT') continue;

  const stats = statsFor(grade.channel_name);
  stats.propTotal += 1;
  if (grade.result === 'CORRECT') stats.propCorrect += 1;
}

const ranked = [...pickers.values()].sort((a, b) => {
  const accuracyDiff = percent(b.pickCorrect, b.pickTotal) - percent(a.pickCorrect, a.pickTotal);

  return accuracyDiff !== 0 ? accuracyDiff : b.pickTotal - a.pickTotal;
});

const lines = [
  '<b>Event results and pick scores</b>',
  `<b>${escapeHtml(evt.event_name)}</b>`,
  `${results.length} fights graded`,
  '',
];

if (ranked.length === 0) {
  lines.push('No picks were available to grade for this event.');
} else {
  ranked.forEach((stats, index) => {
    const props =
      stats.propTotal > 0
        ? ` · props ${stats.propCorrect}/${stats.propTotal} (${percent(stats.propCorrect, stats.propTotal)}%)`
        : '';

    lines.push(
      `${index + 1}. ${escapeHtml(stats.name)} — ${stats.pickCorrect}/${stats.pickTotal} ` +
      `picks (${percent(stats.pickCorrect, stats.pickTotal)}%)${props}`
    );
  });
}

// Fights where nobody (or almost nobody) picked the winner.
const byFight = new Map();

for (const grade of pickGrades) {
  if (grade.result !== 'CORRECT' && grade.result !== 'INCORRECT') continue;

  const entry = byFight.get(grade.fight_order) || { correct: 0, total: 0, winner: grade.winner, a: grade.fighter_a, b: grade.fighter_b };
  entry.total += 1;
  if (grade.result === 'CORRECT') entry.correct += 1;
  byFight.set(grade.fight_order, entry);
}

const missed = [...byFight.values()]
  .filter((entry) => entry.total >= 3 && entry.correct / entry.total <= 0.34)
  .sort((a, b) => a.correct / a.total - b.correct / b.total)
  .slice(0, 3);

if (missed.length > 0) {
  lines.push('', '<b>Fights the pickers missed</b>');

  for (const entry of missed) {
    lines.push(
      `• ${escapeHtml(entry.winner)} won (${entry.correct}/${entry.total} picked it)`
    );
  }
}

const bets = propGrades.filter(
  (grade) =>
    (grade.recommendation_strength === 'best_bet' ||
      grade.recommendation_strength === 'recommended_bet') &&
    (grade.result === 'CORRECT' || grade.result === 'INCORRECT')
);

if (bets.length > 0) {
  lines.push('', '<b>Recommended bets</b>');

  for (const bet of bets.slice(0, 8)) {
    lines.push(
      `${bet.result === 'CORRECT' ? '✅' : '❌'} ${escapeHtml(bet.selection)} ` +
      `(${escapeHtml(bet.channel_name)})`
    );
  }
}

return [{ json: { chat_id: evt.chat_id, notify: evt.notify, text: lines.join('\n') } }];
